/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент таких карт от общего количества карт */
    ROUND(
        100.0 * SUM(CASE WHEN "isstoryspotlight" = 1 AND "istextless" = 0 THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*), 0),
        2
    ) AS "percentage"
FROM "cards";
```

```sql
/* Находим минимальную репутацию среди пользователей */
WITH min_rep AS (
    SELECT MIN(CAST("reputation" AS BIGINT)) AS min_reputation
    FROM "users"
),
/* Определяем пользователей с минимальной репутацией */
lowest_users AS (
    SELECT u."id"
    FROM "users" u
    JOIN min_rep mr ON CAST(u."reputation" AS BIGINT) = mr.min_reputation
)
/* Получаем уникальные названия бейджей, полученных этими пользователями */
SELECT DISTINCT b."name"
FROM "badges" b
JOIN lowest_users lu ON b."userid" = lu."id"
ORDER BY b."name";
```

