/* Соотношение клиентов с валютой EUR к клиентам с валютой CZK */
SELECT
    /* Количество клиентов с EUR */
    SUM(CASE WHEN "currency" = 'EUR' THEN 1 ELSE 0 END)::numeric
    /
    /* Количество клиентов с CZK */
    NULLIF(SUM(CASE WHEN "currency" = 'CZK' THEN 1 ELSE 0 END), 0) AS ratio_eur_to_czk
FROM "customers" c;
```

```sql
/* Сумма трат клиента 38508 на заправках и сумма трат за январь 2012 */
SELECT
    /* Общая сумма трат на заправках */
    SUM(CASE WHEN t."gasstationid" IS NOT NULL THEN t."price" ELSE 0 END) AS total_spent_gasstations,
    /* Сумма трат за январь 2012 */
    SUM(CASE WHEN t."date" >= '2012-01-01' AND t."date" < '2012-02-01' THEN t."price" ELSE 0 END) AS spent_january_2012
FROM "transactions_1k" t
WHERE t."customerid" = '38508'
```
